CREATE TABLE art_sizes (id UUID PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, width_cm NUMERIC(10,2), height_cm NUMERIC(10,2), status VARCHAR(20) NOT NULL, CONSTRAINT ck_art_sizes_status CHECK (status IN ('ACTIVE','ARCHIVED')), CONSTRAINT ck_art_sizes_dimensions CHECK ((code = 'CUSTOM' AND width_cm IS NULL AND height_cm IS NULL) OR (code <> 'CUSTOM' AND width_cm > 0 AND height_cm > 0)));
